from fractions import Fraction
import json

# From the initial curve, its tangent condition gives q = u_tau = 2*tau.
# The PDE pq = u then gives p = tau/2 (extended continuously at tau=0).
p0 = Fraction(1, 2)
q0 = Fraction(2, 1)

# Charpit equations: p'=p, q'=q, u'=2u, x'=q, y'=p.
# Store each expression as {exponent_of_e^s: exact_coefficient}.
computed = {
    "x": {1: q0, 0: -q0},
    "y": {1: p0, 0: Fraction(1, 1) - p0},
    "u": {2: Fraction(1, 1)},
}

options = {
    1: {
        "x": {1: Fraction(3), 0: Fraction(-3)},
        "y": {-1: Fraction(1, 2), 0: Fraction(1, 2)},
        "u": {-2: Fraction(1)},
    },
    2: {
        "x": {1: Fraction(2), 0: Fraction(-2)},
        "y": {2: Fraction(2), 0: Fraction(-1)},
        "u": {0: Fraction(1, 2), -2: Fraction(1, 2)},
    },
    3: {
        "x": {1: Fraction(2), 0: Fraction(-2)},
        "y": {1: Fraction(1, 2), 0: Fraction(1, 2)},
        "u": {2: Fraction(1)},
    },
    4: {
        "x": {-1: Fraction(1), 0: Fraction(-1)},
        "y": {-1: Fraction(-2), 0: Fraction(3)},
        "u": {-2: Fraction(2), 0: Fraction(-1)},
    },
}

def canonical(expression):
    return {k: v for k, v in expression.items() if v}

matches = [
    number for number, expressions in options.items()
    if all(canonical(expressions[name]) == canonical(computed[name])
           for name in ("x", "y", "u"))
]

if len(matches) != 1:
    result = {
        "final_answer": "UNSUPPORTED",
        "evidence": "The exact Charpit expressions did not match exactly one option.",
    }
else:
    number = matches[0]
    result = {
        "final_answer": f"Option {number}",
        "evidence": (
            "Charpit gives p=(tau/2)e^s, q=2tau e^s, u=tau^2 e^(2s); "
            "integrating x'=q and y'=p from (0,tau) gives "
            "x=2tau(e^s-1), y=(tau/2)(e^s+1). Exact coefficient comparison "
            f"matches option {number}."
        ),
    }

print(json.dumps(result))
