import itertools
import json

# Orthography and phonetic forms from the problem.
examples = [
    ("tmi’gn", "[dəmīgən]"),
    ("an’stawteg", "[anəstawtek]"),
    ("gjiansale’wit", "[əkciansalēwit]"),
    ("mgumie’jo’tlatl", "[əmkumiējōdəladəl]"),
    ("amqwanji’j", "[amxʷancīc]"),
    ("e’jnt", "[ējənt]"),
    ("tplutaqan", "[ətpəludaɣan]"),
    ("ge’gwising", "[gēgʷisink]"),
    ("lnu’sgw", "[lənūskw]"),
    ("g’p’ta’q", "[gəbədāx]"),
    ("epsaqtejg", "[epsaxteck]"),
]

def clean_orth(word):
    return word.replace("’", "")

def clean_ipa(ipa):
    return ipa[1:-1].replace("̄", "")

forms = [(clean_orth(o), clean_ipa(p)) for o, p in examples]
orth_alphabet = set("".join(o for o, _ in forms))

# Derive the final spelling/sound correspondence from the examples.
final_g_to_k = [
    (o, p) for o, p in forms if o.endswith("g") and p.endswith("k")
]
assert final_g_to_k
assert all(o.endswith("g") and p.endswith("k") for o, p in final_g_to_k)

# Check that the supplied pairs exhibit phonetic schwa beyond written vowels.
vowels = set("aeiouə")
schwa_witnesses = []
for o, p in forms:
    written_vowels = sum(ch in "aeiou" for ch in o)
    phonetic_vowels = sum(ch in vowels for ch in p)
    if p.count("ə") and phonetic_vowels > written_vowels:
        schwa_witnesses.append(o)
assert schwa_witnesses

target = "alaptək"

# Invert the corpus-supported final g -> k correspondence; treat schwa as
# potentially epenthetic, and enumerate all resulting spellings.
choices = []
for i, ch in enumerate(target):
    if ch == "ə":
        choices.append([""])  # deletion of an epenthetic schwa
    elif ch == "k" and final_g_to_k:
        choices.append(["g"])
    elif ch in orth_alphabet:
        choices.append([ch])
    else:
        choices.append([])

candidates = set()
for parts in itertools.product(*choices):
    candidate = "".join(parts)
    if candidate:
        candidates.add(candidate)

def forward_with_one_epenthetic_schwa(word):
    base = list(word)
    if base and base[-1] == "g":
        base[-1] = "k"
    # The examples attest schwa insertion between adjacent consonants.
    for i in range(1, len(base)):
        left, right = base[i - 1], base[i]
        if left not in "aeiou" and right not in "aeiou":
            yield "".join(base[:i]) + "ə" + "".join(base[i:])

settled = sorted(
    word for word in candidates
    if target in set(forward_with_one_epenthetic_schwa(word))
)
assert len(settled) == 1

print(json.dumps({
    "final_answer": settled[0],
    "evidence": {
        "examples_supporting_final_g_to_k": len(final_g_to_k),
        "examples_witnessing_epenthetic_schwa": len(schwa_witnesses),
        "forward_check": "alaptg -> alaptək",
        "candidate_count": len(settled)
    }
}, separators=(",", ":")))
