import re
import math
from collections import defaultdict

# Interpret each M/L pair as a straight drawn segment. Coordinates are scaled
# integers, so endpoint matching and collinearity tests are exact.
path = """M 24.38698,-19.9365 L 29.3405,-17.62663 M 0.0,7.0 L 0.0,5.46 M 10.35209,0.0 L 10.35209,-7.0986 M 20.49493,-28.84999 L 17.75636,-22.97711 M 20.49493,-21.75139 L 24.38698,-19.9365 M 18.29129,-17.02568 L 20.49493,-21.75139 M 17.75636,-22.97711 L 15.16487,-17.41963 M 10.35209,-7.0986 L 0.0,-7.0986 M 22.10067,8.68911 L 19.34832,10.61633 M 2.5205,-5.64339 L 6.14757,-3.5493 M 10.35209,-4.68508 L 10.35209,0.0 M 10.35209,-7.0986 L 10.35209,-4.68508 M 20.49493,-25.44266 L 20.49493,-28.84999 M 0.0,-7.0986 L 2.5205,-5.64339 M 6.14757,-3.5493 L 2.33608,-1.34873 M 24.85302,6.76189 L 22.10067,8.68911 M 15.93065,-11.96326 L 17.25429,-14.80182 M 20.49493,-21.75139 L 20.49493,-25.44266 M 19.34832,10.61633 L 17.21983,12.10671 L 11.74658,15.93912 M 10.35209,1.96 L 10.35209,3.3712 M 0.0,5.46 L 0.0,0.0 M 4.03732,0.0 L 10.35209,0.0 M 10.35209,7.0 L 7.55703,7.0 M 10.35209,0.0 L 15.93065,-11.96326 M 10.35209,3.3712 L 10.35209,7.0 M 2.33608,-1.34873 L 0.0,0.0 M 34.99586,-14.98949 L 24.85302,6.76189 M 15.16487,-17.41963 L 10.35209,-7.0986 M 11.74658,15.93912 L 11.17484,9.40408 M 0.0,0.0 L 4.03732,0.0 M 11.17484,9.40408 L 10.79637,5.0782 M 29.3405,-17.62663 L 34.99586,-14.98949 M 10.35209,0.0 L 10.35209,1.96 M 10.79637,5.0782 L 10.35209,0.0 M 7.55703,7.0 L 0.0,7.0 M 17.25429,-14.80182 L 18.29129,-17.02568"""

tokens = re.findall(r"M|L|[-+]?(?:\d+(?:\.\d*)?|\.\d+)", path)
segments = []
i = 0
current = None
while i < len(tokens):
    command = tokens[i]
    i += 1
    x = round(float(tokens[i]) * 100000)
    y = round(float(tokens[i + 1]) * 100000)
    i += 2
    point = (x, y)
    if command == "M":
        current = point
    else:
        segments.append((current, point))
        current = point

adj = defaultdict(set)
for a, b in segments:
    if a != b:
        adj[a].add(b)
        adj[b].add(a)

def cross(a, b, c):
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

def dot(u, v):
    return u[0] * v[0] + u[1] * v[1]

def simplify(poly):
    # Remove vertices that merely split a straight side into multiple lines.
    p = list(poly)
    changed = True
    while changed and len(p) >= 3:
        changed = False
        for j in range(len(p)):
            if cross(p[j - 1], p[j], p[(j + 1) % len(p)]) == 0:
                p.pop(j)
                changed = True
                break
    return tuple(p)

def on_segment(a, b, p):
    return (cross(a, b, p) == 0 and
            min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and
            min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))

def segments_intersect(a, b, c, d):
    ab_c, ab_d = cross(a, b, c), cross(a, b, d)
    cd_a, cd_b = cross(c, d, a), cross(c, d, b)
    if ab_c == 0 and on_segment(a, b, c): return True
    if ab_d == 0 and on_segment(a, b, d): return True
    if cd_a == 0 and on_segment(c, d, a): return True
    if cd_b == 0 and on_segment(c, d, b): return True
    return (ab_c > 0) != (ab_d > 0) and (cd_a > 0) != (cd_b > 0)

def simple_polygon(p):
    n = len(p)
    for i in range(n):
        a, b = p[i], p[(i + 1) % n]
        for j in range(i + 1, n):
            if j == i or j == (i + 1) % n or (j + 1) % n == i:
                continue
            c, d = p[j], p[(j + 1) % n]
            if segments_intersect(a, b, c, d):
                return False
    return True

def close(a, b, scale=1e-6):
    return abs(a - b) <= scale * max(1.0, abs(a), abs(b))

def parallel(u, v):
    return abs(u[0] * v[1] - u[1] * v[0]) <= 1e-6 * (
        math.hypot(*u) * math.hypot(*v)
    )

def regular_polygon(p):
    n = len(p)
    lengths = []
    cosines = []
    for i in range(n):
        prev, here, nxt = p[i - 1], p[i], p[(i + 1) % n]
        incoming = (prev[0] - here[0], prev[1] - here[1])
        outgoing = (nxt[0] - here[0], nxt[1] - here[1])
        lengths.append(math.hypot(*outgoing))
        cosines.append(dot(incoming, outgoing) /
                       (math.hypot(*incoming) * math.hypot(*outgoing)))
    return (all(close(x, lengths[0]) for x in lengths) and
            all(close(x, cosines[0]) for x in cosines))

def point_location(poly, x, y):
    # Return 0 on boundary, 1 inside, and -1 outside.
    inside = False
    n = len(poly)
    for i in range(n):
        ax, ay = poly[i]
        bx, by = poly[(i + 1) % n]
        z = (x, y)
        if on_segment((ax, ay), (bx, by), z):
            return 0
        if (ay > y) != (by > y):
            crossing_x = ax + (y - ay) * (bx - ax) / (by - ay)
            if x < crossing_x:
                inside = not inside
    return 1 if inside else -1

def has_interior_stroke(poly):
    # Exclude a candidate outline if a drawn segment passes through its
    # interior (a diagonal or other internal stroke).
    for a, b in segments:
        midpoint = ((a[0] + b[0]) / 2, (a[1] + b[1]) / 2)
        if point_location(poly, *midpoint) == 1:
            return True
    return False

def classify(poly):
    n = len(poly)
    edges = [(poly[(i + 1) % n][0] - poly[i][0],
              poly[(i + 1) % n][1] - poly[i][1]) for i in range(n)]
    turns = [cross(poly[i - 1], poly[i], poly[(i + 1) % n])
             for i in range(n)]
    convex = all(t > 0 for t in turns) or all(t < 0 for t in turns)

    if n == 3:
        right = any(abs(dot(edges[i - 1], edges[i])) <=
                    1e-6 * math.hypot(*edges[i - 1]) * math.hypot(*edges[i])
                    for i in range(3))
        return 4 if right else 3

    if n == 4 and convex:
        parallel_pairs = (parallel(edges[0], edges[2]),
                          parallel(edges[1], edges[3]))
        rectangle = all(
            abs(dot(edges[i - 1], edges[i])) <=
            1e-6 * math.hypot(*edges[i - 1]) * math.hypot(*edges[i])
            for i in range(4)
        )
        lengths = [math.hypot(*e) for e in edges]
        square = rectangle and all(close(x, lengths[0]) for x in lengths)
        if square:
            return 2
        if rectangle:
            return 1
        if all(parallel_pairs):
            return 5
        if sum(parallel_pairs) == 1:
            return 6

    if n == 5:
        if regular_polygon(poly):
            return 9
        return 7 if convex else 8

    if n == 6 and convex and regular_polygon(poly):
        return 10
    return None

# Enumerate every simple cycle in the endpoint graph, without duplicate
# rotations or reversals. A cap prevents pathological exponential runtimes.
nodes = sorted(adj)
cycles = set()
cycle_cap = 500000
overflow = False

for start in nodes:
    def walk(path_nodes, used):
        nonlocal_dummy = None
        global overflow
        if overflow:
            return
        here = path_nodes[-1]
        for nxt in adj[here]:
            if nxt == start and len(path_nodes) >= 3:
                if path_nodes[1] < path_nodes[-1]:
                    cycles.add(tuple(path_nodes))
                    if len(cycles) > cycle_cap:
                        overflow = True
                        return
            elif nxt > start and nxt not in used:
                walk(path_nodes + [nxt], used | {nxt})
    walk([start], {start})
    if overflow:
        break

if overflow:
    print("UNSUPPORTED: cycle enumeration exceeded the safety cap")
    print("CHECK UNKNOWN")
else:
    found = set()
    for cycle in cycles:
        poly = simplify(cycle)
        if len(poly) < 3 or not simple_polygon(poly):
