from fractions import Fraction
import json

c = Fraction(20, -24) - (2 + (-3))

# Differentiate each term of the given polynomial.
coeffs = [
    Fraction(4, 16),  # coefficient of x^3
    -3 * c,            # coefficient of x^2
    Fraction(2, 8),    # coefficient of x
    Fraction(0),       # constant coefficient
]

def evaluate(poly, x):
    value = Fraction(0)
    for coefficient in poly:
        value = value * x + coefficient
    return value

def divide_by_root(poly, root):
    quotient = [poly[0]]
    for coefficient in poly[1:-1]:
        quotient.append(coefficient + root * quotient[-1])
    remainder = poly[-1] + root * quotient[-1]
    if remainder != 0:
        raise ArithmeticError("Not an exact root")
    return quotient

remaining = coeffs[:]
root_multiplicities = []
for root in range(-10, 11):
    multiplicity = 0
    while len(remaining) > 1 and evaluate(remaining, Fraction(root)) == 0:
        remaining = divide_by_root(remaining, Fraction(root))
        multiplicity += 1
    if multiplicity:
        root_multiplicities.append((root, multiplicity))

if len(remaining) != 1:
    print("UNSUPPORTED")
else:
    leading = remaining[0]
    factors = []
    for root, multiplicity in root_multiplicities:
        if root == 0:
            factor = "s"
        elif root > 0:
            factor = f"(s - {root})"
        else:
            factor = f"(s + {-root})"
        factors.append(factor if multiplicity == 1 else f"{factor}^{multiplicity}")

    factorization = str(leading) + "*" + "*".join(factors)

    # Verify that the computed factors reproduce the derivative polynomial.
    reconstructed = [leading]
    for root, multiplicity in root_multiplicities:
        for _ in range(multiplicity):
            next_poly = [Fraction(0)] * (len(reconstructed) + 1)
            for i, coefficient in enumerate(reconstructed):
                next_poly[i] += coefficient
                next_poly[i + 1] -= root * coefficient
            reconstructed = next_poly

    if reconstructed != coeffs:
        print("UNSUPPORTED")
    else:
        print(json.dumps({
            "final_answer": factorization,
            "evidence": {
                "c": str(c),
                "derivative_coefficients_descending": [str(x) for x in coeffs],
                "integer_roots_with_multiplicities": root_multiplicities,
                "factorization_verified": True
            }
        }))
