from fractions import Fraction

# Represent a polynomial as {power: exact coefficient}.
def add(a, b):
    out = dict(a)
    for power, coefficient in b.items():
        out[power] = out.get(power, Fraction(0)) + coefficient
    return {p: c for p, c in out.items() if c}

def multiply(a, b):
    out = {}
    for p, x in a.items():
        for q, y in b.items():
            out[p + q] = out.get(p + q, Fraction(0)) + x * y
    return {p: c for p, c in out.items() if c}

def derivative(poly):
    return {p - 1: p * c for p, c in poly.items() if p > 0}

def show(poly):
    return " + ".join(
        f"({poly[p]})*x^{p}" for p in sorted(poly, reverse=True)
    ) or "0"

c = Fraction(20, -24) - (2 + -3)
function = {
    4: Fraction(1, 16),
    3: -c,
    2: Fraction(1, 8),
    1: Fraction(0),
    0: Fraction(1),
}
expected = derivative(function)

# Expand (1/4)*x*(x - 1)^2 to verify the factored form.
factored = multiply(
    {1: Fraction(1, 4)},
    multiply({1: Fraction(1)}, {2: Fraction(1), 1: Fraction(-2), 0: Fraction(1)}),
)

submitted = {
    3: Fraction(1, 4),
    2: Fraction(57, 24),
    1: Fraction(1, 4),
}

print("c =", c)
print("Derivative coefficients:", show(expected))
print("Factored candidate: (1/4)*x*(x - 1)^2")
print("Expansion of factored candidate:", show(factored))
print("Submitted coefficients:", show(submitted))
print("Factorization check:", "PASS" if factored == expected else "FAIL")
print("Submitted-answer check:", "PASS" if submitted == expected else "FAIL")
