from fractions import Fraction
from math import gcd, lcm
import json

# Represent A + B*sqrt(39) exactly, with rational A and B.
def add(u, v):
    return (u[0] + v[0], u[1] + v[1])

def neg(u):
    return (-u[0], -u[1])

def sub(u, v):
    return add(u, neg(v))

def mul(u, v):
    return (u[0] * v[0] + 39 * u[1] * v[1],
            u[0] * v[1] + u[1] * v[0])

def div(u, v):
    norm = v[0] * v[0] - 39 * v[1] * v[1]
    assert norm != 0
    return ( (u[0] * v[0] - 39 * u[1] * v[1]) / norm,
             (u[1] * v[0] - u[0] * v[1]) / norm )

def format_pair(u):
    den = lcm(u[0].denominator, u[1].denominator)
    a = u[0].numerator * (den // u[0].denominator)
    b = u[1].numerator * (den // u[1].denominator)
    common = gcd(gcd(abs(a), abs(b)), den)
    a, b, den = a // common, b // common, den // common

    if b < 0:
        radical = f"{abs(b)}√39"
        middle = f" - {radical}" if a else f"-{radical}"
    elif b > 0:
        radical = f"{b}√39"
        middle = f" + {radical}" if a else radical
    else:
        middle = ""

    if a and b:
        numerator = f"{a}{middle}"
    elif a:
        numerator = str(a)
    else:
        numerator = middle

    if den == 1:
        return numerator
    if b:
        return f"({numerator})/{den}"
    return f"{a}/{den}"

# With two equal variables a,a, the constraints give
# 3a^2 - 18a + 14 = 0, hence a = 3 ± √39/3.
# The plus choice makes the third variable negative; the minus choice is feasible.
assert 39 < 81
assert 4 * 39 > 81
a = (Fraction(3), Fraction(-1, 3))
z = (Fraction(3), Fraction(2, 3))
assert add(add(a, a), z) == (Fraction(9), Fraction(0))
assert add(mul(a, a), mul((Fraction(2), Fraction(0)), mul(a, z))) == (
    Fraction(14), Fraction(0)
)

# For the feasible choice, compute r=xyz exactly.
r = mul(mul(a, a), z)

# The objective is 36 - 2660/(126-r). Its minimum occurs at maximum xyz:
# the feasible set's boundary has xyz=0, while an interior extremum has
# at most two distinct coordinates by Lagrange multipliers.
denominator = sub((Fraction(126), Fraction(0)), r)
answer = sub((Fraction(36), Fraction(0)),
             div((Fraction(2660), Fraction(0)), denominator))

evidence = (
    "Let r=xyz. The objective simplifies to 36-2660/(126-r), so minimizing "
    "it maximizes r. Boundary points have r=0; an interior extremum has two "
    "equal variables. The feasible repeated-root choice is "
    f"a={format_pair(a)}, z={format_pair(z)}, giving r={format_pair(r)}. "
    "Exact substitution gives the stated minimum."
)

print(json.dumps({
    "final_answer": format_pair(answer),
    "evidence": evidence
}))
