    "size": "huge large tiny massive enormous small midsize medium-size normal-size",
    "shape": "spherical rectangular prismlike circular square triangular pyramidal",
    "age": "ancient new old-fashioned archaic brand-new old",
    "color": "maroon pink blue cyan black magenta brown white gray teal crimson violet green yellow indigo",
    "origin": "russian thai vietnamese bangladeshi brazilian mexican egyptian chinese american pakistani japanese iranian nigerian filipino indian turkish german ethiopian",
    "material": "canvas paper fiberglass glass wool leather wood rubber iron cloth cardboard plastic steel",
    "purpose": "hiking driving walking drinking exercise smoking typing eating snorkeling whittling",
}
word_class = {
    word: category
    for category, words in classes.items()
    for word in words.split()
}

witnesses = [
    "maroon good bottle",                 # color < opinion
    "bangladeshi spherical spoon",        # origin < shape
    "triangular large new house",         # shape < size < age
    "normal-size walking shirt",          # size < purpose
    "iranian eating glass screwdriver",   # origin < purpose < material
    "paper ancient bag",                  # material < age
]

edges = set()
for sentence in witnesses:
    sequence = [
        word_class[word]
        for word in sentence.split()
        if word in word_class
    ]
    for i in range(len(sequence)):
        for j in range(i + 1, len(sequence)):
            if sequence[i] != sequence[j]:
                edges.add((sequence[i], sequence[j]))

categories = set(classes)
reach = {category: set() for category in categories}
for left, right in edges:
    reach[left].add(right)

# Transitive closure of the precedence constraints.
for middle in categories:
    for left in categories:
        if middle in reach[left]:
            reach[left].update(reach[middle])

if any(category in reach[category] for category in categories):
    print(json.dumps({
        "final_answer": "UNSUPPORTED",
        "evidence": "The precedence constraints contain a cycle."
    }))
else:
    options = {
        "A": "massive hiking wool old-fashioned green silly",
        "B": "repulsive midsize typing plastic brand-new pyramidal ethiopian",
        "C": "ethiopian rectangular medium-size driving glass ancient repulsive",
