import itertools
import json

def nonempty_subsets(items):
    for mask in range(1, 1 << len(items)):
        yield {items[i] for i in range(len(items)) if mask & (1 << i)}

pair_cells = list(itertools.product((False, True), repeat=2))
single_cells = [(False,), (True,)]

def find_counterexample(cells, premise, conclusion):
    for model in nonempty_subsets(cells):
        if premise(model) and not conclusion(model):
            return sorted(model)
    return None

# Each tuple records which predicates hold of an individual.
arguments = {
    "original": (
        pair_cells,
        lambda m: any(g and not c for g, c in m),
        lambda m: any(c and not g for g, c in m),
    ),
    "A": (
        pair_cells,
        lambda m: any(h and not p for h, p in m),
        lambda m: any(p and not h for h, p in m),
    ),
    "B": (
        single_cells,
        lambda m: any(not selfish for (selfish,) in m),
        lambda m: any(not selfish for (selfish,) in m),
    ),
    "C": (
        pair_cells,
        lambda m: any(motive and not effect for motive, effect in m),
        lambda m: any(effect and not motive for motive, effect in m),
    ),
    "D": (
        pair_cells,
        lambda m: any(south and not cantonese for south, cantonese in m),
        lambda m: any(cantonese and not south for south, cantonese in m),
    ),
}

counterexamples = {
    name: find_counterexample(cells, premise, conclusion)
    for name, (cells, premise, conclusion) in arguments.items()
}
invalid = [name for name, witness in counterexamples.items()
           if witness is not None and name != "original"]
valid = [name for name, witness in counterexamples.items()
         if witness is None and name != "original"]

# The four predicate-truth types exhaust all possible finite models for
# these existential statements: only the types present in a model matter.
answer = ", ".join(invalid) if invalid else "UNSUPPORTED"
print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "invalid_options": invalid,
        "valid_options": valid,
        "counterexamples_by_predicate_truth_type": {
            name: witness for name, witness in counterexamples.items()
            if witness is not None
        }
    }))
