import itertools
import json

nationalities = ("South Korea", "France", "Britain", "Germany")
languages = {
    "South Korea": {"Korean"},
    "France": {"French", "German"},
    "Britain": {"English", "Korean"},
    "Germany": {"Korean", "French", "English", "German"},
}

options = {
    "A": ("Britain", "Germany", "South Korea", "France"),
    "B": ("France", "Britain", "Germany", "South Korea"),
    "C": ("Germany", "Britain", "France", "South Korea"),
    "D": ("Germany", "Britain", "South Korea", "France"),
}

valid_orders = []
for order in itertools.permutations(nationalities):
    room = {nationality: i for i, nationality in enumerate(order)}

    if room["South Korea"] <= room["Germany"]:
        continue

    def communicates(a, b):
        return bool(languages[a] & languages[b])

    neighbors = {
        nationality: [
            order[j]
            for j in (room[nationality] - 1, room[nationality] + 1)
            if 0 <= j < len(order)
        ]
        for nationality in nationalities
    }
    communication_counts = {
        nationality: sum(communicates(nationality, neighbor)
                         for neighbor in neighbors[nationality])
        for nationality in nationalities
    }

    if (communication_counts["South Korea"] == 0
            and communication_counts["France"] == 0
            and communication_counts["Britain"] == 1):
        valid_orders.append(order)

matching_options = [
    letter for letter, order in options.items()
    if order in valid_orders
]

if len(valid_orders) == 1 and len(matching_options) == 1:
    order = valid_orders[0]
    result = {
        "final_answer": f'{matching_options[0]}. ' + ", ".join(order),
        "evidence": {
            "valid_order_count": len(valid_orders),
            "room_order": list(order),
            "communication_counts": {
                nationality: sum(
                    bool(languages[nationality] & languages[neighbor])
                    for neighbor in (
                        order[i] for i in (order.index(nationality) - 1,
                                           order.index(nationality) + 1)
                        if 0 <= i < len(order)
                    )
                )
                for nationality in nationalities
            },
        },
    }
else:
    result = {
        "final_answer": "UNSUPPORTED",
        "evidence": {
            "valid_order_count": len(valid_orders),
            "matching_options": matching_options,
        },
    }

print(json.dumps(result))
