def translate(text):
    def replace_capital(match):
        country = match.group(1).lower()
        city = match.group(2).lower()
        try:
            return str(CAPITALS[(country, city)])
        except KeyError:
            raise ValueError(f"Unsupported capital fact: {match.group(0)}")

    text = re.sub(
        r"The capital of ([A-Za-z]+) is ([A-Za-z]+)\.",
        replace_capital,
        text,
    )
    text = text.replace("is less than or equal to", "<=")
    text = text.replace("is greater than", ">")
    return text


def evaluate(node):
    if isinstance(node, ast.Constant):
        if isinstance(node.value, bool):
            return node.value
        if isinstance(node.value, int):
            return Fraction(node.value)
        raise ValueError(f"Unsupported constant: {node.value!r}")

    if isinstance(node, ast.UnaryOp):
        value = evaluate(node.operand)
        if isinstance(node.op, ast.Not):
            return not value
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return value
        raise ValueError(f"Unsupported unary operator: {type(node.op).__name__}")

    if isinstance(node, ast.BoolOp):
        values = [evaluate(value) for value in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
        raise ValueError(f"Unsupported Boolean operator: {type(node.op).__name__}")

    if isinstance(node, ast.BinOp):
        left, right = evaluate(node.left), evaluate(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return left / right
        raise ValueError(f"Unsupported arithmetic operator: {type(node.op).__name__}")

    if isinstance(node, ast.Compare):
        left = evaluate(node.left)
        for op, comparator in zip(node.ops, node.comparators):
            right = evaluate(comparator)
            if isinstance(op, ast.Lt):
                result = left < right
            elif isinstance(op, ast.LtE):
                result = left <= right
            elif isinstance(op, ast.Gt):
                result = left > right
            elif isinstance(op, ast.GtE):
                result = left >= right
            elif isinstance(op, ast.Eq):
                result = left == right
            elif isinstance(op, ast.NotEq):
                result = left != right
            else:
                raise ValueError(f"Unsupported comparison: {type(op).__name__}")
            if not result:
                return False
            left = right
        return True

    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
        args = [evaluate(arg) for arg in node.args]
        if node.func.id == "max":
            return max(args)
        if node.func.id == "min":
            return min(args)

    raise ValueError(f"Unsupported syntax: {ast.dump(node)}")


results = {}
for label, expression in EXPRESSIONS.items():
    translated = translate(expression)
    results[label] = evaluate(ast.parse(translated, mode="eval").body)
    print(f"{label} = {results[label]}")

true_options = [label for label, value in results.items() if value]
print("True option(s):", ", ".join(true_options) if true_options else "none")

if len(true_options) == 1 and results["B"]:
    print("CHECK PASS")
else:
    print("CHECK FAIL")
