from itertools import permutations

# Interpret “can communicate” to mean that two neighbors share at least
# one language both can speak. Assume everyone speaks their native language.
languages = {
    "South Korea": {"Korean"},
    "France": {"French", "German"},
    "Britain": {"English", "Korean"},
    "Germany": {"Korean", "French", "English", "German"},
}

options = {
    "A": ("Britain", "Germany", "South Korea", "France"),
    "B": ("France", "Britain", "Germany", "South Korea"),
    "C": ("Germany", "Britain", "France", "South Korea"),
    "D": ("Germany", "Britain", "South Korea", "France"),
}
submitted = "D"

def violations(order):
    room = {nationality: i + 1 for i, nationality in enumerate(order)}

    def communicates(a, b):
        return bool(languages[a] & languages[b])

    neighbors = {
        nationality: [
            order[j]
            for j in (i - 1, i + 1)
            if 0 <= j < len(order)
        ]
        for i, nationality in enumerate(order)
    }

    problems = []
    if room["South Korea"] <= room["Germany"]:
        problems.append("Korean room number is not larger than German room number")

    if any(communicates("South Korea", n) for n in neighbors["South Korea"]):
        problems.append("Korean can communicate with a neighbor")

    if any(communicates("France", n) for n in neighbors["France"]):
        problems.append("French can communicate with a neighbor")

    british_contacts = sum(
        communicates("Britain", n) for n in neighbors["Britain"]
    )
    if british_contacts != 1:
        problems.append(
            f"British can communicate with {british_contacts} neighbors, not one"
        )

    return problems

valid_orders = [
    order for order in permutations(languages)
    if not violations(order)
]

print("Valid room orders (smallest to largest):")
for order in valid_orders:
    print(" -> ".join(order))

selected_order = options[submitted]
selected_violations = violations(selected_order)
print(f"\nSelected option {submitted}: {' -> '.join(selected_order)}")
print("Selected-option violations:")
for problem in selected_violations:
    print("-", problem)

if len(valid_orders) == 1 and valid_orders[0] == options["C"]:
    print("\nCHECK FAIL: the submitted answer D is not valid; exhaustive enumeration gives C.")
else:
    print("\nCHECK UNKNOWN: enumeration did not produce the expected unique order.")
